import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Card,
  CardContent,
  Chip,
  Link,
  Slider,
  Stack,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import ApiService from '../../services/api';
import { MSME_SIMPLIFIED_ACTION_LABELS } from '../../constants/msmeSimplifiedUi';

const CarbonMethodologySettingsCard: React.FC = () => {
  const [maintenanceUnitPriceInr, setMaintenanceUnitPriceInr] = useState(200);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const persistMaintenanceUnitPrice = useCallback(async (value: number) => {
    const clamped = Math.min(1000, Math.max(50, Math.round(value)));
    setMaintenanceUnitPriceInr(clamped);
    try {
      await ApiService.updateMaintenanceUnitPrice(clamped);
      setError(null);
    } catch (err) {
      console.error('Failed to sync maintenance unit price:', err);
      setError('Could not save maintenance unit price. Try again.');
    }
  }, []);

  useEffect(() => {
    let active = true;
    const load = async () => {
      setLoading(true);
      try {
        const response = await ApiService.getMaintenanceUnitPrice();
        const price = Number(
          (response as { data?: { maintenanceUnitPriceInr?: number } })?.data?.maintenanceUnitPriceInr
        );
        if (active && Number.isFinite(price) && price > 0) {
          setMaintenanceUnitPriceInr(price);
        }
      } catch (err) {
        console.error('Failed to load maintenance unit price:', err);
        if (active) {
          setError('Could not load saved maintenance unit price.');
        }
      } finally {
        if (active) {
          setLoading(false);
        }
      }
    };
    void load();
    return () => {
      active = false;
    };
  }, []);

  return (
    <Card id="carbon-methodology" variant="outlined">
      <CardContent>
        <Typography variant="h6" sx={{ fontWeight: 700, mb: 0.5 }}>
          {MSME_SIMPLIFIED_ACTION_LABELS.maintenanceSettingsTitle}
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          Counted maintenance jobs use Quantity and unit service_unit, visit, or job, at 0.1 kg CO₂e per service unit, and stay out of the 1% estimate check. This ₹ rate applies only when the bill has no service count. Full methodology appears in exported ISO 14064 PDFs.
        </Typography>

        <Typography variant="subtitle2" gutterBottom>
          Maintenance spend proxy
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
          Rupee-only AMC and repair vouchers divide the amount by this ₹ per service unit, then apply 0.1 kg CO₂e per unit. Those rows stay in the 1% estimate check. Adjust the rate to match a typical job-card visit.
        </Typography>

        {error && (
          <Alert severity="warning" sx={{ mb: 2 }}>
            {error}
          </Alert>
        )}

        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ sm: 'center' }}>
          <Slider
            value={maintenanceUnitPriceInr}
            onChange={(_, value) => { void persistMaintenanceUnitPrice(value as number); }}
            min={50}
            max={1000}
            step={10}
            valueLabelDisplay="auto"
            disabled={loading}
            aria-label="Maintenance service unit price in INR"
            sx={{ maxWidth: { sm: 420 }, flex: 1 }}
          />
          <Chip
            label={`₹${maintenanceUnitPriceInr} / service unit`}
            color="default"
            variant="outlined"
          />
        </Stack>

        <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1.5 }}>
          Also used on{' '}
          <Link component={RouterLink} to="/emissions-reduction-targets">
            Emissions reduction targets
          </Link>{' '}
          for scenario modelling. Changes apply to the next carbon recalculation.
        </Typography>
      </CardContent>
    </Card>
  );
};

export default CarbonMethodologySettingsCard;
