import React, { useCallback, useEffect, useRef, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  FormControl,
  FormControlLabel,
  FormLabel,
  Grid,
  MenuItem,
  Radio,
  RadioGroup,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import {
  AccountCircleOutlined,
  FactoryOutlined,
  SettingsOutlined,
} from '@mui/icons-material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import { Link as RouterLink, Navigate, useLocation, useNavigate } from 'react-router-dom';
import { DISCLOSURE_PROFILE_PATH, PLANT_PROFILE_PATH, PROFILE_PAGES, profilePageFromPath } from '../constants/workspacePages';
import WorkspacePageHeader from './shared/WorkspacePageHeader';
import ApiService from '../services/api';
import { queryKeys } from '../constants/queryKeys';
import MsmeProfileEssentialsEditor from './MsmeProfileEssentialsEditor';
import CarbonMethodologySettingsCard from './carbon/CarbonMethodologySettingsCard';
import OrganizationalBoundaryEase, { organizationalBoundaryIssues, type OrgBoundaryDraft } from './ghg/OrganizationalBoundaryEase';
import BoundaryPicture, { type BoundaryPictureOps } from './ghg/BoundaryPicture';
import ManufacturingWorkflowPlanner from './ManufacturingWorkflowPlanner';
import MyCompanyRequiredNotice from './MyCompanyRequiredNotice';
import { myCompanyPageChecks } from '../utils/myCompanyRequired';
import { MSME_SIMPLIFIED_ACTION_LABELS } from '../constants/msmeSimplifiedUi';

interface MSMEProfileData {
  _id?: string;
  companyName?: string;
  companyType?: string;
  industry?: string;
  businessDomain?: string;
  udyamRegistrationNumber?: string;
  gstNumber?: string;
  panNumber?: string;
  carbonScore?: number;
  isVerified?: boolean;
  status?: string;
  listedCompanyProfile?: {
    listingStatus?: string;
    cinNumber?: string;
    stockExchanges?: string[];
    isin?: string;
    scripCode?: string;
  };
  contact?: {
    email?: string;
    phone?: string;
    address?: {
      street?: string;
      city?: string;
      state?: string;
      pincode?: string;
      country?: string;
    };
  };
  business?: {
    annualTurnover?: number;
    numberOfEmployees?: number;
    manufacturingUnits?: number;
    manufacturingWorkflow?: any;
    solarPower?: {
      installedCapacityKw?: number;
      annualGenerationKwh?: number;
      annualUsageKwh?: number;
      netMeteringEnabled?: boolean;
      lastUpdatedAt?: string;
    };
  };
  manufacturingProfile?: {
    msmeType?: string;
    industrySector?: string;
    nicCode?: string;
    yearOfEstablishment?: number;
    locationCity?: string;
    locationState?: string;
    locationCountry?: string;
    installationLatitude?: number;
    installationLongitude?: number;
    numberOfEmployees?: number;
    plantAreaSqft?: number;
    operationalDaysPerYear?: number;
    primaryEnergySource?: string;
    electricityDiscomId?: string;
    backupEnergySource?: string;
    mainFuelsUsed?: string[];
    waterSource?: string;
    wasteManagementPractice?: string;
    keyProducts?: string[];
    productionCapacityPerMonth?: number;
    productionCapacityUnit?: string;
    supplyChainType?: string;
    logisticsMode?: string;
    certifications?: string[];
    esgMaturityLevel?: string;
    digitalizationLevel?: string;
    carbonAccountingPractice?: string;
    powerConsumptionKwhPerMonth?: number;
    waterConsumptionKlPerMonth?: number;
    chemicalsConsumptionKgPerMonth?: number;
    wasteRecycledKgPerMonth?: number;
    wasteWaterKlPerMonth?: number;
    solarInstallationKw?: number;
    solarGenerationKwhPerMonth?: number;
    importedRawMaterialsKgPerMonth?: number;
    outputProductsKgPerMonth?: number;
    servicesDeliveredPerMonth?: number;
    complianceCertifications?: string[];
    iso14064Aligned?: boolean;
    iso14067Aligned?: boolean;
    ghgProtocolAligned?: boolean;
    regulatoryExposure?: string[];
    exportActivity?: boolean;
    clusterAssociation?: string;
    ghgOrganizationalBoundary?: {
      consolidationApproach?: string;
      reportingEntityDescription?: string;
      includedLegalEntities?: Array<{
        name?: string;
        relationshipType?: string;
        consolidationBasis?: string;
      }>;
      jointVentureEmissionAllocation?: string;
      franchisesOrOutsourcedOperationsTreatment?: string;
      nonControlledOperationsExcluded?: boolean;
      organizationalBoundaryNotes?: string;
      onSiteFuelCombustion?: string;
      fleetControl?: string;
      logisticsArrangement?: string;
      reportingEquitySharePercent?: number;
      singleLegalEntity?: boolean;
      holdingCompany?: {
        name?: string;
        ownershipPercent?: number;
        country?: string;
        includedInBoundary?: boolean;
      };
      subsidiaries?: Array<{ name?: string; ownershipPercent?: number; operationalControl?: boolean }>;
      jointVentures?: Array<{ name?: string; ownershipPercent?: number; operationalControl?: boolean }>;
      lastReviewedAt?: string;
    };
  };
  operations?: {
    sites?: Array<{
      name?: string;
      city?: string;
      state?: string;
      country?: string;
    }>;
    vehicles?: Array<{
      type?: string;
      fuelType?: string;
      ownership?: string;
      count?: number;
      monthlyDistanceKm?: number;
    }>;
    subsidiaries?: Array<{
      name?: string;
      controlModel?: string;
    }>;
    metrics?: {
      powerConsumptionKwhPerMonth?: number;
      waterConsumptionKlPerMonth?: number;
      chemicalsConsumptionKgPerMonth?: number;
      fuelUsageLitersPerMonth?: number;
      recycledWasteKgPerMonth?: number;
      wasteWaterKlPerMonth?: number;
      solarInstallationKw?: number;
      solarGenerationKwhPerMonth?: number;
      importedRawMaterialsKgPerMonth?: number;
      outputProductsKgPerMonth?: number;
      servicesDeliveredPerMonth?: number;
      annualTurnoverInr?: number;
      complianceCertifications?: string[];
      iso14064Aligned?: boolean;
      iso14067Aligned?: boolean;
      ghgProtocolAligned?: boolean;
    };
    operationsDataFeed?: {
      selectedChemicalOptions?: string[];
      selectedWaterTreatmentOptions?: string[];
    };
    ghgOperationalBoundary?: {
      reportingPeriodType?: string;
      reportingPeriodEndMonth?: number;
      baseYear?: number;
      materialityThresholdPercent?: number;
      scope1StationaryCombustion?: boolean;
      scope1MobileCombustion?: boolean;
      scope1ProcessEmissions?: boolean;
      scope1FugitiveEmissions?: boolean;
      scope2LocationBased?: boolean;
      scope2MarketBased?: boolean;
      scope3CategoriesIncluded?: number[];
      scope3OutOfBoundarySummary?: string;
      biogenicCo2Approach?: string;
      operationalBoundaryDefinitionSummary?: string;
      operationalBoundaryNotes?: string;
    };
  };
}

const MSMEProfileSection: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const profilePage = profilePageFromPath(location.pathname);
  const queryClient = useQueryClient();
  const cachedProfile = queryClient.getQueryData<{ data?: MSMEProfileData }>(queryKeys.msme.profile);
  const [profile, setProfile] = useState<MSMEProfileData | null>(cachedProfile?.data ?? null);
  const [loading, setLoading] = useState(!cachedProfile?.data);
  const profileRef = useRef(profile);
  profileRef.current = profile;
  const [error, setError] = useState<string | null>(null);
  const [orgBoundaryDraft, setOrgBoundaryDraft] = useState<OrgBoundaryDraft>({
    consolidationApproach: 'operational_control',
    reportingEntityDescription: '',
    includedLegalEntities: [] as Array<{
      name: string;
      relationshipType: string;
      consolidationBasis: string;
    }>,
    jointVentureEmissionAllocation: 'not_applicable',
    franchisesOrOutsourcedOperationsTreatment: '',
    nonControlledOperationsExcluded: true,
    organizationalBoundaryNotes: '',
    onSiteFuelCombustion: 'unknown',
    fleetControl: 'unknown',
    logisticsArrangement: 'unknown',
    reportingEquitySharePercent: '',
    singleLegalEntity: false,
    holdingCompany: { name: '', ownershipPercent: '', country: 'India', includedInBoundary: false },
    subsidiaries: [] as Array<{ name: string; ownershipPercent: string; operationalControl: boolean }>,
    jointVentures: [] as Array<{ name: string; ownershipPercent: string; operationalControl: boolean }>,
  });
  const [orgBoundarySaving, setOrgBoundarySaving] = useState(false);
  const [orgBoundaryFeedback, setOrgBoundaryFeedback] = useState<string | null>(null);
  const [exportActivityDraft, setExportActivityDraft] = useState<boolean | null>(null);
  const [exportIntentSaving, setExportIntentSaving] = useState(false);
  const [exportIntentFeedback, setExportIntentFeedback] = useState<string | null>(null);
  const [listedCompanyDraft, setListedCompanyDraft] = useState({
    listingStatus: 'unlisted',
    cinNumber: '',
    stockExchanges: [] as string[],
    isin: '',
    scripCode: ''
  });
  const [listedCompanySaving, setListedCompanySaving] = useState(false);
  const [listedCompanyFeedback, setListedCompanyFeedback] = useState<string | null>(null);
  const [opsBoundary, setOpsBoundary] = useState<BoundaryPictureOps | null>(null);
  const [opsBoundarySaved, setOpsBoundarySaved] = useState(false);
  const [boundariesEditing, setBoundariesEditing] = useState(false);
  const [sourcedOperations, setSourcedOperations] = useState<{
    unitNames: string[];
    powerKwh?: number;
    fuelLiters?: number;
  }>({ unitNames: [] });

  const loadProfile = useCallback(async () => {
    setError(null);
    if (!profileRef.current) {
      setLoading(true);
    }
    try {
      const response = await ApiService.getMSMEProfile();
      const nextProfile = response?.data || null;
      setProfile(nextProfile);
      if (response) {
        queryClient.setQueryData(queryKeys.msme.profile, response);
      }
    } catch (err) {
      if (!profileRef.current) {
        setProfile(null);
        setError(err instanceof Error ? err.message : 'Unable to load MSME profile.');
      }
    } finally {
      setLoading(false);
    }
  }, [queryClient]);

  useEffect(() => {
    void loadProfile();
  }, [loadProfile]);

  useEffect(() => {
    if (!profile) return;
    const boundary = myCompanyPageChecks(profile).find((page) => page.id === 'boundaries');
    if (boundary && !boundary.complete) setBoundariesEditing(true);
  }, [profile]);

  useEffect(() => {
    if (profilePage?.id !== 'disclosure') return undefined;
    let cancelled = false;
    Promise.resolve(ApiService.getManufacturingWorkflow())
      .then((response: {
        data?: {
          ghgOperationalBoundary?: BoundaryPictureOps;
          units?: Array<{ name?: string }>;
          operationsData?: { powerConsumptionKwhPerMonth?: number; fuelUsageLitersPerMonth?: number };
        };
      }) => {
        if (cancelled) return;
        const data = response?.data;
        const saved = data?.ghgOperationalBoundary;
        setOpsBoundary(saved && typeof saved === 'object' ? saved : null);
        setOpsBoundarySaved(Boolean(saved && typeof saved === 'object'));
        const units = data && Array.isArray(data.units) ? data.units : [];
        const operationsData = data?.operationsData;
        setSourcedOperations({
          unitNames: units.map((unit) => String(unit?.name || '').trim()).filter(Boolean),
          powerKwh: Number(operationsData?.powerConsumptionKwhPerMonth) || undefined,
          fuelLiters: Number(operationsData?.fuelUsageLitersPerMonth) || undefined,
        });
      })
      .catch(() => {
        if (!cancelled) {
          setOpsBoundary(null);
          setOpsBoundarySaved(false);
          setSourcedOperations({ unitNames: [] });
        }
      });
    return () => {
      cancelled = true;
    };
  }, [profilePage?.id]);

  useEffect(() => {
    if (!profile) return;
    const ob = profile.manufacturingProfile?.ghgOrganizationalBoundary;
    if (ob && typeof ob === 'object') {
      setOrgBoundaryDraft({
        consolidationApproach: ob.consolidationApproach || 'operational_control',
        reportingEntityDescription: String(ob.reportingEntityDescription || ''),
        includedLegalEntities: Array.isArray(ob.includedLegalEntities)
          ? ob.includedLegalEntities.map((row) => ({
            name: String(row?.name || ''),
            relationshipType: String(row?.relationshipType || ''),
            consolidationBasis: String(row?.consolidationBasis || '')
          }))
          : [],
        jointVentureEmissionAllocation: ob.jointVentureEmissionAllocation || 'not_applicable',
        franchisesOrOutsourcedOperationsTreatment: String(ob.franchisesOrOutsourcedOperationsTreatment || ''),
        nonControlledOperationsExcluded: ob.nonControlledOperationsExcluded !== false,
        organizationalBoundaryNotes: String(ob.organizationalBoundaryNotes || ''),
        onSiteFuelCombustion: String(ob.onSiteFuelCombustion || 'unknown'),
        fleetControl: String(ob.fleetControl || 'unknown'),
        logisticsArrangement: String(ob.logisticsArrangement || 'unknown'),
        reportingEquitySharePercent: ob.reportingEquitySharePercent != null ? String(ob.reportingEquitySharePercent) : '',
        singleLegalEntity: Boolean(ob.singleLegalEntity),
        holdingCompany: {
          name: String(ob.holdingCompany?.name || ''),
          ownershipPercent: ob.holdingCompany?.ownershipPercent != null ? String(ob.holdingCompany.ownershipPercent) : '',
          country: String(ob.holdingCompany?.country || 'India'),
          includedInBoundary: ob.holdingCompany?.includedInBoundary !== false && Boolean(ob.holdingCompany?.name),
        },
        subsidiaries: Array.isArray(ob.subsidiaries)
          ? ob.subsidiaries.map((row) => ({
            name: String(row?.name || ''),
            ownershipPercent: row?.ownershipPercent != null ? String(row.ownershipPercent) : '',
            operationalControl: row?.operationalControl !== false,
          }))
          : [],
        jointVentures: Array.isArray(ob.jointVentures)
          ? ob.jointVentures.map((row) => ({
            name: String(row?.name || ''),
            ownershipPercent: row?.ownershipPercent != null ? String(row.ownershipPercent) : '',
            operationalControl: Boolean(row?.operationalControl),
          }))
          : [],
      });
    }
  }, [profile]);

  useEffect(() => {
    if (!profile) return;
    const listed = profile.listedCompanyProfile;
    if (listed && typeof listed === 'object') {
      setListedCompanyDraft({
        listingStatus: listed.listingStatus || 'unlisted',
        cinNumber: String(listed.cinNumber || ''),
        stockExchanges: Array.isArray(listed.stockExchanges) ? listed.stockExchanges : [],
        isin: String(listed.isin || ''),
        scripCode: String(listed.scripCode || '')
      });
    }
  }, [profile]);

  useEffect(() => {
    if (!profile) return;
    const storedExport = profile.manufacturingProfile?.exportActivity;
    setExportActivityDraft(typeof storedExport === 'boolean' ? storedExport : null);
  }, [profile]);

  const saveExportIntent = async () => {
    if (!profile) return;
    if (exportActivityDraft === null) {
      setExportIntentFeedback('Choose whether you export outside India.');
      return;
    }
    setExportIntentSaving(true);
    setExportIntentFeedback(null);
    try {
      await ApiService.updateMSMEProfile({
        manufacturingProfile: {
          ...(profile.manufacturingProfile || {}),
          exportActivity: exportActivityDraft,
        },
      });
      const response = await ApiService.getMSMEProfile();
      setProfile(response?.data || null);
      setExportIntentFeedback(
        exportActivityDraft
          ? 'Export compliance enabled — CBAM and buyer audit tools are now available.'
          : 'Export compliance hidden — India market tools remain available.'
      );
    } catch (err) {
      setExportIntentFeedback(err instanceof Error ? err.message : 'Unable to save export preference.');
    } finally {
      setExportIntentSaving(false);
    }
  };

  const saveListedCompanyProfile = async () => {
    if (!profile) return;
    setListedCompanySaving(true);
    setListedCompanyFeedback(null);
    try {
      await ApiService.updateMSMEProfile({
        listedCompanyProfile: {
          listingStatus: listedCompanyDraft.listingStatus,
          cinNumber: listedCompanyDraft.cinNumber.trim().toUpperCase() || undefined,
          stockExchanges: listedCompanyDraft.stockExchanges,
          isin: listedCompanyDraft.isin.trim().toUpperCase() || undefined,
          scripCode: listedCompanyDraft.scripCode.trim() || undefined
        }
      });
      const response = await ApiService.getMSMEProfile();
      setProfile(response?.data || null);
      setListedCompanyFeedback('Listed company profile saved. BRSR/XBRL filing profile will sync to Compliance Hub.');
    } catch (err) {
      setListedCompanyFeedback(err instanceof Error ? err.message : 'Unable to save listed company profile.');
    } finally {
      setListedCompanySaving(false);
    }
  };

  const saveOrganizationalBoundary = async () => {
    if (!profile) return;
    setOrgBoundarySaving(true);
    setOrgBoundaryFeedback(null);
    const issues = organizationalBoundaryIssues(orgBoundaryDraft);
    if (issues.length > 0) {
      setOrgBoundaryFeedback(issues[0]);
      setOrgBoundarySaving(false);
      return;
    }
    try {
      const toParty = (row: { name: string; ownershipPercent: string; operationalControl: boolean }) => ({
        name: row.name.trim(),
        ownershipPercent: Number(row.ownershipPercent) || undefined,
        operationalControl: row.operationalControl,
      });
      const subsidiaries = (orgBoundaryDraft.subsidiaries || []).map(toParty).filter((row) => row.name);
      const jointVentures = (orgBoundaryDraft.jointVentures || []).map(toParty).filter((row) => row.name);
      const holding = orgBoundaryDraft.holdingCompany || {
        name: '',
        ownershipPercent: '',
        country: 'India',
        includedInBoundary: false,
      };
      const holdingName = holding.name.trim();
      const includedLegalEntities = [
        ...orgBoundaryDraft.includedLegalEntities
          .map((row) => ({
            name: row.name.trim(),
            relationshipType: row.relationshipType.trim(),
            consolidationBasis: row.consolidationBasis.trim()
          }))
          .filter((row) => row.name.length > 0),
        ...subsidiaries.map((row) => ({
          name: row.name,
          relationshipType: 'subsidiary',
          consolidationBasis: orgBoundaryDraft.consolidationApproach,
        })),
        ...jointVentures.map((row) => ({
          name: row.name,
          relationshipType: 'joint_venture',
          consolidationBasis: orgBoundaryDraft.jointVentureEmissionAllocation,
        })),
        ...(holdingName ? [{
          name: holdingName,
          relationshipType: 'holding',
          consolidationBasis: orgBoundaryDraft.consolidationApproach,
        }] : []),
      ];
      await ApiService.updateMSMEProfile({
        operations: {
          ...(profile.operations || {}),
          subsidiaries: subsidiaries.map((row) => ({
            name: row.name,
            controlModel: row.operationalControl ? 'operational_control' : 'equity_share',
          })),
        },
        manufacturingProfile: {
          ...(profile.manufacturingProfile || {}),
          ghgOrganizationalBoundary: {
            consolidationApproach: orgBoundaryDraft.consolidationApproach,
            reportingEntityDescription: orgBoundaryDraft.reportingEntityDescription,
            includedLegalEntities,
            jointVentureEmissionAllocation: orgBoundaryDraft.jointVentureEmissionAllocation,
            franchisesOrOutsourcedOperationsTreatment: orgBoundaryDraft.franchisesOrOutsourcedOperationsTreatment,
            nonControlledOperationsExcluded: orgBoundaryDraft.nonControlledOperationsExcluded,
            organizationalBoundaryNotes: orgBoundaryDraft.organizationalBoundaryNotes,
            onSiteFuelCombustion: orgBoundaryDraft.onSiteFuelCombustion || 'unknown',
            fleetControl: orgBoundaryDraft.fleetControl || 'unknown',
            logisticsArrangement: orgBoundaryDraft.logisticsArrangement || 'unknown',
            reportingEquitySharePercent: orgBoundaryDraft.reportingEquitySharePercent
              ? Number(orgBoundaryDraft.reportingEquitySharePercent)
              : undefined,
            singleLegalEntity: Boolean(orgBoundaryDraft.singleLegalEntity),
            holdingCompany: holdingName ? {
              name: holdingName,
              ownershipPercent: Number(holding.ownershipPercent) || undefined,
              country: holding.country,
              includedInBoundary: true,
            } : undefined,
            subsidiaries,
            jointVentures,
            lastReviewedAt: new Date().toISOString()
          }
        }
      });
      const response = await ApiService.getMSMEProfile();
      setProfile(response?.data || null);
      setOrgBoundaryFeedback('Organizational boundary saved to your profile.');
    } catch (err) {
      setOrgBoundaryFeedback(err instanceof Error ? err.message : 'Unable to save organizational boundary.');
    } finally {
      setOrgBoundarySaving(false);
    }
  };

  const street = String(profile?.contact?.address?.street || '');
  const city = String(profile?.contact?.address?.city || '');
  const state = String(profile?.contact?.address?.state || '');
  const streetLower = street.toLowerCase();
  const profileAddress = [
    street,
    city && !streetLower.includes(city.toLowerCase()) ? city : '',
    state && !streetLower.includes(state.toLowerCase()) ? state : '',
    profile?.contact?.address?.pincode,
    profile?.contact?.address?.country,
  ]
    .filter(Boolean)
    .join(', ');

  const activeProfilePage = profilePage ?? PROFILE_PAGES[0];

  if (location.pathname === PLANT_PROFILE_PATH) {
    return <Navigate to="/operations/units" replace />;
  }

  if (location.pathname === DISCLOSURE_PROFILE_PATH) {
    return <Navigate to="/msme-profile/boundaries" replace />;
  }

  return (
    <Box>
      <WorkspacePageHeader
        title={activeProfilePage.navLabel}
        description={
          activeProfilePage.id === 'disclosure'
            ? 'Boundaries are built from Company profile, Energy and meters, Manufacturing units, Direct emissions, and Value chain.'
            : 'Company details, the export choice, and leftover registration sit on this page. Plant, energy, and emissions pages come next.'
        }
      />

      {profile && !loading ? (
        <MyCompanyRequiredNotice
          profile={profile}
          pageId={activeProfilePage.id === 'disclosure' ? 'boundaries' : 'company'}
        />
      ) : null}

      {profile && !loading ? (
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 2 }}>
          {PROFILE_PAGES.map((page) => (
            <Button
              key={page.id}
              component={RouterLink}
              to={page.path}
              size="small"
              variant={profilePage?.id === page.id ? 'contained' : 'outlined'}
            >
              {page.label}
            </Button>
          ))}
        </Stack>
      ) : null}

      {profile && !loading && (profilePage?.id === 'overview' || !profilePage) && (
        <>
          <Card variant="outlined" sx={{ mb: 2, overflow: 'hidden', borderLeft: '6px solid #0f766e' }}>
            <CardContent>
              <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} flexWrap="wrap" useFlexGap alignItems="center" sx={{ mb: 2 }}>
                <Typography variant="h6" sx={{ fontWeight: 800, flex: 1 }}>
                  {profile.companyName || 'Your company'}
                </Typography>
                {profile.carbonScore != null ? (
                  <Chip label={`Carbon score ${Math.round(profile.carbonScore)}`} color="success" variant="outlined" />
                ) : null}
                <Chip
                  label={
                    typeof profile.manufacturingProfile?.exportActivity === 'boolean'
                      ? (profile.manufacturingProfile.exportActivity ? 'Export enabled' : 'India market only')
                      : 'Export choice required'
                  }
                  color={
                    profile.manufacturingProfile?.exportActivity
                      ? 'primary'
                      : (typeof profile.manufacturingProfile?.exportActivity === 'boolean' ? 'default' : 'warning')
                  }
                  variant="outlined"
                />
                <Chip
                  label={profile.isVerified || profile.status === 'verified' ? 'Verified' : 'Pending verification'}
                  color={profile.isVerified || profile.status === 'verified' ? 'success' : 'warning'}
                  variant="outlined"
                />
              </Stack>
              <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} flexWrap="wrap" useFlexGap>
                <Button variant="outlined" size="small" startIcon={<SettingsOutlined />} onClick={() => navigate('/settings')}>
                  Account settings
                </Button>
                <Button variant="outlined" size="small" startIcon={<FactoryOutlined />} onClick={() => navigate('/operations')}>
                  Open operations
                </Button>
                <Button variant="text" size="small" startIcon={<AccountCircleOutlined />} onClick={() => navigate('/settings')}>
                  Personal details
                </Button>
              </Stack>
            </CardContent>
          </Card>
          <MsmeProfileEssentialsEditor profile={profile} onSaved={loadProfile} />
          <Card variant="outlined" sx={{ mt: 2, mb: 2, borderRadius: 3, background: 'linear-gradient(90deg, rgba(15,118,110,0.08), rgba(15,118,110,0))' }}>
            <CardContent>
              <FormControl required>
                <FormLabel sx={{ fontWeight: 800, color: 'text.primary', mb: 0.5 }}>
                  Export activity
                </FormLabel>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5, maxWidth: 640 }}>
                  Required. Choose one. Export unlocks CBAM, buyer audit, and other export compliance tools.
                </Typography>
                <RadioGroup
                  value={exportActivityDraft === null ? '' : exportActivityDraft ? 'yes' : 'no'}
                  onChange={(_, value) => setExportActivityDraft(value === 'yes')}
                >
                  <FormControlLabel value="yes" control={<Radio />} label="We export goods or services outside India" />
                  <FormControlLabel value="no" control={<Radio />} label="India market only" />
                </RadioGroup>
              </FormControl>
              <Stack direction="row" spacing={1} sx={{ mt: 1 }} alignItems="center">
                <Button variant="contained" size="small" onClick={saveExportIntent} disabled={exportIntentSaving || exportActivityDraft === null}>
                  {exportIntentSaving ? 'Saving…' : 'Save export preference'}
                </Button>
                {exportIntentFeedback ? (
                  <Typography variant="caption" color="text.secondary">{exportIntentFeedback}</Typography>
                ) : null}
              </Stack>
            </CardContent>
          </Card>
          <Typography variant="subtitle1" sx={{ fontWeight: 800, mb: 1 }}>
            More registration details
          </Typography>
          <Box
            sx={{
              display: 'grid',
              gridTemplateColumns: { xs: '1fr 1fr', md: 'repeat(4, 1fr)' },
              gap: 1.25,
              mb: 2,
            }}
          >
            {[
              ['Company type', profile.companyType || 'Not provided'],
              ['Business domain', profile.businessDomain || 'Not provided'],
              ['NIC code', profile.manufacturingProfile?.nicCode || 'Not provided'],
              ['Days / year', profile.manufacturingProfile?.operationalDaysPerYear ?? 'Not provided'],
              ['Digitalization', profile.manufacturingProfile?.digitalizationLevel || 'Not provided'],
              ['ESG maturity', profile.manufacturingProfile?.esgMaturityLevel || 'Not provided'],
              ['Registered address', profileAddress || 'Not provided'],
            ].map(([label, value]) => (
              <Box
                key={String(label)}
                sx={{
                  p: 1.5,
                  borderRadius: 2,
                  bgcolor: 'action.hover',
                  border: '1px solid',
                  borderColor: 'divider',
                  gridColumn: label === 'Registered address' ? { xs: '1 / -1', md: 'span 2' } : undefined,
                }}
              >
                <Typography variant="caption" color="text.secondary">{label}</Typography>
                <Typography variant="body2" sx={{ fontWeight: 700 }}>{String(value)}</Typography>
              </Box>
            ))}
          </Box>
        </>
      )}

      {loading ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', py: 6 }}>
              <CircularProgress />
            </Box>
          ) : error ? (
            <Alert severity="warning" sx={{ mb: 2 }}>
              {error}
            </Alert>
          ) : !profile ? (
            <Alert
              severity="info"
              action={(
                <Button color="inherit" size="small" onClick={() => navigate('/msme-registration')}>
                  Complete registration
                </Button>
              )}
            >
              MSME profile is not available yet.
            </Alert>
          ) : profilePage && profilePage.id !== 'overview' ? (
            <Grid container spacing={2}>
              {profilePage.id === 'disclosure' ? (
              <Grid item xs={12}>
                <Typography variant="body1" color="text.secondary" sx={{ mb: 2 }}>
                  Built from Company profile, Energy and meters, Manufacturing units, Direct emissions, and Value chain.
                </Typography>
                <BoundaryPicture
                  org={{
                    companyName: profile.companyName,
                    consolidationApproach: orgBoundaryDraft.consolidationApproach,
                    includedLegalEntities: orgBoundaryDraft.includedLegalEntities,
                    subsidiaries: orgBoundaryDraft.subsidiaries,
                    jointVentures: orgBoundaryDraft.jointVentures,
                    holdingCompany: orgBoundaryDraft.holdingCompany,
                    nonControlledOperationsExcluded: orgBoundaryDraft.nonControlledOperationsExcluded,
                    franchisesOrOutsourcedOperationsTreatment: orgBoundaryDraft.franchisesOrOutsourcedOperationsTreatment,
                  }}
                  operations={opsBoundary}
                  operationsSaved={opsBoundarySaved}
                />
                <Box
                  sx={{
                    display: 'grid',
                    gridTemplateColumns: { xs: '1fr', md: '1fr 1fr' },
                    gap: 1.25,
                    mb: 2,
                  }}
                >
                  {[
                    {
                      label: 'Company',
                      value: profile.companyName || 'Not filled yet',
                      href: '/msme-profile',
                      edit: 'Edit company',
                    },
                    {
                      label: 'Export activity',
                      value: typeof profile.manufacturingProfile?.exportActivity === 'boolean'
                        ? (profile.manufacturingProfile.exportActivity ? 'Exports outside India' : 'India market only')
                        : 'Not chosen yet',
                      href: '/msme-profile',
                      edit: 'Edit export activity',
                    },
                    {
                      label: 'Energy source',
                      value: profile.manufacturingProfile?.primaryEnergySource || 'Not filled yet',
                      href: '/operations',
                      edit: 'Edit energy and meters',
                    },
                    {
                      label: 'Monthly electricity',
                      value: sourcedOperations.powerKwh ? `${sourcedOperations.powerKwh} kWh / month` : 'Not filled yet',
                      href: '/operations',
                      edit: 'Edit monthly electricity',
                    },
                    {
                      label: 'Monthly fuel',
                      value: sourcedOperations.fuelLiters ? `${sourcedOperations.fuelLiters} litres / month` : 'Not filled yet',
                      href: '/operations',
                      edit: 'Edit monthly fuel',
                    },
                    {
                      label: 'Manufacturing units',
                      value: sourcedOperations.unitNames.length > 0 ? sourcedOperations.unitNames.join(', ') : 'Not filled yet',
                      href: '/operations/units',
                      edit: 'Edit units',
                    },
                  ].map((row) => (
                    <Box
                      key={row.label}
                      sx={{
                        p: 1.5,
                        borderRadius: 2,
                        border: '1px solid',
                        borderColor: 'divider',
                        display: 'flex',
                        justifyContent: 'space-between',
                        gap: 1,
                        alignItems: 'center',
                      }}
                    >
                      <Box>
                        <Typography variant="caption" color="text.secondary">{row.label}</Typography>
                        <Typography variant="body2" sx={{ fontWeight: 700 }}>{row.value}</Typography>
                      </Box>
                      <Button component={RouterLink} to={row.href} size="small" variant="outlined">
                        {row.edit}
                      </Button>
                    </Box>
                  ))}
                </Box>
                <Stack direction="row" spacing={1} sx={{ mb: 2 }}>
                  <Button
                    variant={boundariesEditing ? 'outlined' : 'contained'}
                    onClick={() => setBoundariesEditing((open) => !open)}
                  >
                    {boundariesEditing ? 'Done' : 'Edit boundary settings'}
                  </Button>
                  <Button component={RouterLink} to="/operations/scope-1" size="small" variant="text">
                    Edit direct emissions
                  </Button>
                  <Button component={RouterLink} to="/operations/scope-3" size="small" variant="text">
                    Edit value chain
                  </Button>
                </Stack>
                {boundariesEditing ? (
                <Accordion variant="outlined" expanded>
                  <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                    <Box>
                      <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
                        Correct boundary settings
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        {MSME_SIMPLIFIED_ACTION_LABELS.expertModeHint}
                      </Typography>
                    </Box>
                  </AccordionSummary>
                  <AccordionDetails>
                    <Stack spacing={2}>
              <Card>
                <CardContent>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 1 }}>
                      Listed company (BRSR / SEBI XBRL)
                    </Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                      If your MSME is also listed on BSE or NSE, provide CIN and exchange details here. These sync to
                      Compliance Hub for SEBI BRSR XBRL filing.
                    </Typography>
                    {listedCompanyFeedback && (
                      <Alert
                        severity={listedCompanyFeedback.includes('saved') ? 'success' : 'warning'}
                        sx={{ mb: 2 }}
                      >
                        {listedCompanyFeedback}
                      </Alert>
                    )}
                    <Grid container spacing={2}>
                      <Grid item xs={12} md={6}>
                        <TextField
                          select
                          fullWidth
                          label="Listing status"
                          value={listedCompanyDraft.listingStatus}
                          onChange={(e) => setListedCompanyDraft((d) => ({
                            ...d,
                            listingStatus: e.target.value,
                            cinNumber: e.target.value === 'unlisted' ? '' : d.cinNumber,
                          }))}
                        >
                          <MenuItem value="unlisted">Unlisted MSME</MenuItem>
                          <MenuItem value="listed">Listed (BSE/NSE)</MenuItem>
                          <MenuItem value="subsidiary_of_listed">Subsidiary of listed group</MenuItem>
                          <MenuItem value="public_sector">Public sector enterprise</MenuItem>
                        </TextField>
                      </Grid>
                      {listedCompanyDraft.listingStatus !== 'unlisted' ? (
                      <Grid item xs={12} md={6}>
                        <TextField
                          fullWidth
                          label="CIN"
                          value={listedCompanyDraft.cinNumber}
                          onChange={(e) => setListedCompanyDraft((d) => ({
                            ...d,
                            cinNumber: e.target.value.toUpperCase()
                          }))}
                          placeholder="e.g. L12345MH2020PLC000001"
                        />
                      </Grid>
                      ) : null}
                      {(listedCompanyDraft.listingStatus === 'listed'
                        || listedCompanyDraft.listingStatus === 'subsidiary_of_listed') && (
                        <>
                          <Grid item xs={12} md={6}>
                            <TextField
                              select
                              fullWidth
                              label="Stock exchange"
                              value={listedCompanyDraft.stockExchanges[0] || ''}
                              onChange={(e) => setListedCompanyDraft((d) => ({
                                ...d,
                                stockExchanges: e.target.value ? [e.target.value] : []
                              }))}
                            >
                              <MenuItem value="BSE">BSE</MenuItem>
                              <MenuItem value="NSE">NSE</MenuItem>
                              <MenuItem value="both">BSE and NSE</MenuItem>
                            </TextField>
                          </Grid>
                          <Grid item xs={12} md={6}>
                            <TextField
                              fullWidth
                              label="ISIN"
                              value={listedCompanyDraft.isin}
                              onChange={(e) => setListedCompanyDraft((d) => ({
                                ...d,
                                isin: e.target.value.toUpperCase()
                              }))}
                            />
                          </Grid>
                          <Grid item xs={12} md={6}>
                            <TextField
                              fullWidth
                              label="Scrip code"
                              value={listedCompanyDraft.scripCode}
                              onChange={(e) => setListedCompanyDraft((d) => ({
                                ...d,
                                scripCode: e.target.value
                              }))}
                            />
                          </Grid>
                        </>
                      )}
                      <Grid item xs={12}>
                        <Button
                          variant="contained"
                          onClick={saveListedCompanyProfile}
                          disabled={listedCompanySaving}
                        >
                          {listedCompanySaving ? 'Saving…' : 'Save listed company profile'}
                        </Button>
                      </Grid>
                    </Grid>
                  </CardContent>
                </Card>

              <Card>
                <CardContent>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 1 }}>
                      Which sites count as your company?
                    </Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                      Pick how you group sites. Most factories use “We run the plants”. Fuel, power, and supplier categories stay under Operations.
                    </Typography>
                    {orgBoundaryFeedback && (
                      <Alert severity={orgBoundaryFeedback.includes('saved') ? 'success' : 'warning'} sx={{ mb: 2 }}>
                        {orgBoundaryFeedback}
                      </Alert>
                    )}
                    <OrganizationalBoundaryEase
                      value={orgBoundaryDraft}
                      onChange={setOrgBoundaryDraft}
                      disabled={orgBoundarySaving}
                    />
                    <Stack direction="row" spacing={1} sx={{ mt: 2 }}>
                      <Button variant="contained" onClick={saveOrganizationalBoundary} disabled={orgBoundarySaving}>
                        {orgBoundarySaving ? 'Saving…' : 'Save organizational boundary'}
                      </Button>
                    </Stack>
                  </CardContent>
                </Card>

                <CarbonMethodologySettingsCard />
                    </Stack>
                  </AccordionDetails>
                </Accordion>
                ) : null}
                <ManufacturingWorkflowPlanner
                  isEmbeddedInOperationsPage
                  calculationOnly
                  showMethodology={boundariesEditing}
                />
              </Grid>
              ) : null}
            </Grid>
          ) : null}

      {!loading && !error && profile && !profilePage ? <Navigate to="/msme-profile" replace /> : null}
    </Box>
  );
};

export default MSMEProfileSection;
